import Foundation

/// Every Lifestream event, with its closed sets, uniqueness and cohort flag compiled in. Generated by `midgar gen --write` from registry/signals.yaml. Edit the registry, not this file.
public enum MidgarSignal: Sendable, Equatable {
    /// The app was opened. Reserved: No MidgarKit or app code records it yet; it stays accepted so the worker's event set does not shrink.
    case appLaunch
    /// Daily, weekly and monthly active installs.
    case appActive(period: Period)
    /// The first-run introduction was finished. Reserved: Helia marks onboarding complete but only logs it; no code sends the event yet.
    case onboardingComplete
    /// How often the purchase screen is shown, and from where in the app.
    case paywallView(placement: Placement)
    /// Purchases completed in the app, by product.
    case paywallPurchase(product: String)
    /// How a purchase you started ended, and for which product.
    case paywallCheckout(outcome: Outcome, product: String)
    /// First-run steps before a purchase.
    case funnelStep(step: FunnelStep)
    /// The screen with other Midgar apps was opened, and from where in the app.
    case portalOpen(storefront: Storefront? = nil, placement: Placement)
    /// Another Midgar app was shown on that screen.
    case impression(appId: String, storefront: Storefront? = nil, placement: Placement)
    /// Another Midgar app was tapped on that screen.
    case tap(appId: String, storefront: Storefront? = nil, placement: Placement)
    /// The App Store page of another Midgar app finished loading from that screen.
    case loaded(appId: String, storefront: Storefront? = nil, placement: Placement)
    /// Another Midgar app was opened from that screen.
    case launch(appId: String, storefront: Storefront? = nil, placement: Placement)
    /// The App Store sheet for another Midgar app was shown at a fitting moment.
    case overlay(appId: String, storefront: Storefront? = nil, placement: Placement)
    /// Daily numbers on how fast the app starts and how much memory it uses, so slow versions get fixed.
    case metricsDaily(coldLaunchMs: Double? = nil, hangSecondsPerHour: Double? = nil, foregroundSeconds: Double? = nil, peakMemoryMB: Double? = nil)
    /// Counts of crashes, freezes and heavy disk or processor use, so they get fixed.
    case metricsDiagnostics(crashes: Int? = nil, hangs: Int? = nil, diskWrites: Int? = nil, cpuExceptions: Int? = nil)
    /// How often the system ended the app while you used it, for memory, for freezing or after a fault, and how often for memory in the background, so those get fixed.
    case metricsExits(foregroundMemory: Int? = nil, foregroundWatchdog: Int? = nil, foregroundAbnormal: Int? = nil, backgroundMemory: Int? = nil)
    /// Whether the app crashed, froze or was ended by the system on a day, so the share of installs with a clean day is known.
    case healthCrashed(kind: CrashKind)
    /// Which failures you ran into, from a fixed list, so the common ones get fixed.
    case errorHit(domain: FaultDomain, code: FaultCode)
    /// How many of the week's active installs are free, on a trial, paying or lapsed.
    case appTier
    /// Which parts of the app get used in a week, and whether by free or paying installs, so the ones worth building on are known.
    case featureUse(feature: String)
    /// How soon after installing you first got what the app is for.
    case valueFirst(within: ValueFirstWithin)
    /// What led up to a purchase made in the app, namely where the purchase screen was opened from, how often it had been shown and how long the app had been installed.
    case purchaseStory(placement: Placement? = nil, viewsBefore: PurchaseStoryViewsBefore)
    /// When a subscription's renewal is turned off, how long it had run and on how many of the last fourteen days the app was opened.
    case renewalOff(tenure: RenewalOffTenure, activeDays: RenewalOffActiveDays)

    /// How often one install may send an event.
    public enum Uniqueness: String, Sendable, CaseIterable {
        case each = "each"
        case daily = "daily"
        case weekly = "weekly"
        case monthly = "monthly"
        case lifetime = "lifetime"
        case perPeriod = "per-period"
    }

    /// The closed set Period; the worker stores any other value as `other`.
    public enum Period: String, Sendable, CaseIterable {
        case day, week, month
    }

    /// The closed set Placement; the worker stores any other value as `other`.
    public enum Placement: String, Sendable, CaseIterable {
        case settings, entry, onboarding, launch, paywall, feature, limit, moment
    }

    /// The closed set Outcome; the worker stores any other value as `other`.
    public enum Outcome: String, Sendable, CaseIterable {
        case started, purchased, pending, cancelled, failed
    }

    /// The closed set FunnelStep; the worker stores any other value as `other`.
    public enum FunnelStep: String, Sendable, CaseIterable {
        case samplePlayed = "sample_played", addMusicOpened = "add_music_opened", libraryFilled = "library_filled", importSucceeded = "import_succeeded", importFailed = "import_failed", trialStarted = "trial_started", pickerCancelled = "picker_cancelled", wifiTransferOpened = "wifi_transfer_opened", importNothingFound = "import_nothing_found", importUnsupported = "import_unsupported", importArchive = "import_archive", importAlreadyPresent = "import_already_present"
        case secondLookOffered = "second_look_offered", secondLookStarted = "second_look_started"
    }

    /// The closed set Storefront; the worker stores any other value as `other`.
    public enum Storefront: String, Sendable, CaseIterable {
        case ad, ae, af, ag, ai, al, am, ao, aq, ar, `as`, at
        case au, aw, ax, az, ba, bb, bd, be, bf, bg, bh, bi
        case bj, bl, bm, bn, bo, bq, br, bs, bt, bv, bw, by
        case bz, ca, cc, cd, cf, cg, ch, ci, ck, cl, cm, cn
        case co, cr, cu, cv, cw, cx, cy, cz, de, dj, dk, dm
        case `do`, dz, ec, ee, eg, eh, er, es, et, fi, fj, fk
        case fm, fo, fr, ga, gb, gd, ge, gf, gg, gh, gi, gl
        case gm, gn, gp, gq, gr, gs, gt, gu, gw, gy, hk, hm
        case hn, hr, ht, hu, id, ie, il, im, `in`, io, iq, ir
        case `is`, it, je, jm, jo, jp, ke, kg, kh, ki, km, kn
        case kp, kr, kw, ky, kz, la, lb, lc, li, lk, lr, ls
        case lt, lu, lv, ly, ma, mc, md, me, mf, mg, mh, mk
        case ml, mm, mn, mo, mp, mq, mr, ms, mt, mu, mv, mw
        case mx, my, mz, na, nc, ne, nf, ng, ni, nl, no, np
        case nr, nu, nz, om, pa, pe, pf, pg, ph, pk, pl, pm
        case pn, pr, ps, pt, pw, py, qa, re, ro, rs, ru, rw
        case sa, sb, sc, sd, se, sg, sh, si, sj, sk, sl, sm
        case sn, so, sr, ss, st, sv, sx, sy, sz, tc, td, tf
        case tg, th, tj, tk, tl, tm, tn, to, tr, tt, tv, tw
        case tz, ua, ug, um, us, uy, uz, va, vc, ve, vg, vi
        case vn, vu, wf, ws, ye, yt, za, zm, zw
    }

    /// The closed set CrashKind; the worker stores any other value as `other`.
    public enum CrashKind: String, Sendable, CaseIterable {
        case crash, hang, memory, watchdog
    }

    /// The closed set FaultDomain; the worker stores any other value as `other`.
    public enum FaultDomain: String, Sendable, CaseIterable {
        case purchase, restore, network, ai, `import`, sync, playback, storage
    }

    /// The closed set FaultCode; the worker stores any other value as `other`.
    public enum FaultCode: String, Sendable, CaseIterable {
        case offline, timeout, server, refused, quota, payment, notFound = "not_found", unsupported, corrupt, full, denied, unknown
    }

    /// The closed set Tier; the worker stores any other value as `other`.
    public enum Tier: String, Sendable, CaseIterable {
        case free, trial, paid, lapsed, unknown
    }

    /// The closed set ValueFirstWithin; the worker stores any other value as `other`.
    public enum ValueFirstWithin: String, Sendable, CaseIterable {
        case firstSession = "first_session", day0, week1, later
    }

    /// The closed set PurchaseStoryViewsBefore; the worker stores any other value as `other`.
    public enum PurchaseStoryViewsBefore: String, Sendable, CaseIterable {
        case none, one, twoThree = "two_three", fourNine = "four_nine", tenPlus = "ten_plus"
    }

    /// The closed set Age; the worker stores any other value as `other`.
    public enum Age: String, Sendable, CaseIterable {
        case day0, week1, month1, quarter1, older, unknown
    }

    /// The closed set RenewalOffTenure; the worker stores any other value as `other`.
    public enum RenewalOffTenure: String, Sendable, CaseIterable {
        case firstMonth = "first_month", quarter1, half1, year1, longer
    }

    /// The closed set RenewalOffActiveDays; the worker stores any other value as `other`.
    public enum RenewalOffActiveDays: String, Sendable, CaseIterable {
        case none, oneTwo = "one_two", threeSix = "three_six", sevenPlus = "seven_plus"
    }

    /// The event name on the wire.
    public var name: String {
        switch self {
        case .appLaunch: return "app.launch"
        case .appActive: return "app.active"
        case .onboardingComplete: return "onboarding.complete"
        case .paywallView: return "paywall.view"
        case .paywallPurchase: return "paywall.purchase"
        case .paywallCheckout: return "paywall.checkout"
        case .funnelStep: return "funnel.step"
        case .portalOpen: return "portal_open"
        case .impression: return "impression"
        case .tap: return "tap"
        case .loaded: return "loaded"
        case .launch: return "launch"
        case .overlay: return "overlay"
        case .metricsDaily: return "metrics.daily"
        case .metricsDiagnostics: return "metrics.diagnostics"
        case .metricsExits: return "metrics.exits"
        case .healthCrashed: return "health.crashed"
        case .errorHit: return "error.hit"
        case .appTier: return "app.tier"
        case .featureUse: return "feature.use"
        case .valueFirst: return "value.first"
        case .purchaseStory: return "purchase.story"
        case .renewalOff: return "renewal.off"
        }
    }

    /// Every event name the registry declares.
    public static let allNames: [String] = ["app.launch", "app.active", "onboarding.complete", "paywall.view", "paywall.purchase", "paywall.checkout", "funnel.step", "portal_open", "impression", "tap", "loaded", "launch", "overlay", "metrics.daily", "metrics.diagnostics", "metrics.exits", "health.crashed", "error.hit", "app.tier", "feature.use", "value.first", "purchase.story", "renewal.off"]

    /// The props the event sends, without the cohort and the context, which MidgarKit stamps.
    public var props: [String: MidgarSignalValue] {
        switch self {
        case .appLaunch: return [:]
        case .appActive(let period): return ["period": .string(period.rawValue)]
        case .onboardingComplete: return [:]
        case .paywallView(let placement): return ["placement": .string(placement.rawValue)]
        case .paywallPurchase(let product): return ["product": .string(product)]
        case .paywallCheckout(let outcome, let product): return ["outcome": .string(outcome.rawValue), "product": .string(product)]
        case .funnelStep(let step): return ["step": .string(step.rawValue)]
        case .portalOpen(let storefront, let placement):
            var props: [String: MidgarSignalValue] = ["placement": .string(placement.rawValue)]
            if let storefront { props["storefront"] = .string(storefront.rawValue) }
            return props
        case .impression(let appId, let storefront, let placement):
            var props: [String: MidgarSignalValue] = ["appId": .string(appId), "placement": .string(placement.rawValue)]
            if let storefront { props["storefront"] = .string(storefront.rawValue) }
            return props
        case .tap(let appId, let storefront, let placement):
            var props: [String: MidgarSignalValue] = ["appId": .string(appId), "placement": .string(placement.rawValue)]
            if let storefront { props["storefront"] = .string(storefront.rawValue) }
            return props
        case .loaded(let appId, let storefront, let placement):
            var props: [String: MidgarSignalValue] = ["appId": .string(appId), "placement": .string(placement.rawValue)]
            if let storefront { props["storefront"] = .string(storefront.rawValue) }
            return props
        case .launch(let appId, let storefront, let placement):
            var props: [String: MidgarSignalValue] = ["appId": .string(appId), "placement": .string(placement.rawValue)]
            if let storefront { props["storefront"] = .string(storefront.rawValue) }
            return props
        case .overlay(let appId, let storefront, let placement):
            var props: [String: MidgarSignalValue] = ["appId": .string(appId), "placement": .string(placement.rawValue)]
            if let storefront { props["storefront"] = .string(storefront.rawValue) }
            return props
        case .metricsDaily(let coldLaunchMs, let hangSecondsPerHour, let foregroundSeconds, let peakMemoryMB):
            var props: [String: MidgarSignalValue] = [:]
            if let coldLaunchMs { props["coldLaunchMs"] = .double(coldLaunchMs) }
            if let hangSecondsPerHour { props["hangSecondsPerHour"] = .double(hangSecondsPerHour) }
            if let foregroundSeconds { props["foregroundSeconds"] = .double(foregroundSeconds) }
            if let peakMemoryMB { props["peakMemoryMB"] = .double(peakMemoryMB) }
            return props
        case .metricsDiagnostics(let crashes, let hangs, let diskWrites, let cpuExceptions):
            var props: [String: MidgarSignalValue] = [:]
            if let crashes { props["crashes"] = .int(crashes) }
            if let hangs { props["hangs"] = .int(hangs) }
            if let diskWrites { props["diskWrites"] = .int(diskWrites) }
            if let cpuExceptions { props["cpuExceptions"] = .int(cpuExceptions) }
            return props
        case .metricsExits(let foregroundMemory, let foregroundWatchdog, let foregroundAbnormal, let backgroundMemory):
            var props: [String: MidgarSignalValue] = [:]
            if let foregroundMemory { props["foregroundMemory"] = .int(foregroundMemory) }
            if let foregroundWatchdog { props["foregroundWatchdog"] = .int(foregroundWatchdog) }
            if let foregroundAbnormal { props["foregroundAbnormal"] = .int(foregroundAbnormal) }
            if let backgroundMemory { props["backgroundMemory"] = .int(backgroundMemory) }
            return props
        case .healthCrashed(let kind): return ["kind": .string(kind.rawValue)]
        case .errorHit(let domain, let code): return ["domain": .string(domain.rawValue), "code": .string(code.rawValue)]
        case .appTier: return [:]
        case .featureUse(let feature): return ["feature": .string(feature)]
        case .valueFirst(let within): return ["within": .string(within.rawValue)]
        case .purchaseStory(let placement, let viewsBefore):
            var props: [String: MidgarSignalValue] = ["viewsBefore": .string(viewsBefore.rawValue)]
            if let placement { props["placement"] = .string(placement.rawValue) }
            return props
        case .renewalOff(let tenure, let activeDays): return ["tenure": .string(tenure.rawValue), "activeDays": .string(activeDays.rawValue)]
        }
    }

    /// How often one install may send this event.
    public var uniqueness: Uniqueness {
        switch self {
        case .appLaunch: return .each
        case .appActive: return .perPeriod
        case .onboardingComplete: return .each
        case .paywallView: return .each
        case .paywallPurchase: return .each
        case .paywallCheckout: return .each
        case .funnelStep: return .lifetime
        case .portalOpen: return .each
        case .impression: return .each
        case .tap: return .each
        case .loaded: return .each
        case .launch: return .each
        case .overlay: return .each
        case .metricsDaily: return .each
        case .metricsDiagnostics: return .each
        case .metricsExits: return .each
        case .healthCrashed: return .daily
        case .errorHit: return .daily
        case .appTier: return .weekly
        case .featureUse: return .weekly
        case .valueFirst: return .lifetime
        case .purchaseStory: return .each
        case .renewalOff: return .each
        }
    }

    /// Whether MidgarKit stamps the install week on this event.
    public var carriesCohort: Bool {
        switch self {
        case .appActive, .funnelStep, .valueFirst: return true
        default: return false
        }
    }

    /// What MidgarKit can add to an event from what the install knows about itself: whether it pays, and how long ago it was installed.
    public enum Context: String, Sendable, CaseIterable {
        case age, tier
    }

    /// The context MidgarKit stamps on this event.
    public var context: [Context] {
        switch self {
        case .appTier, .featureUse: return [.tier]
        case .purchaseStory: return [.age]
        default: return []
        }
    }

    /// Whether the event is a story: MidgarKit holds it for some hours before sending it and the server counts each of its props on its own, so it cannot be lined up with a purchase.
    public var isStory: Bool {
        switch self {
        case .purchaseStory, .renewalOff: return true
        default: return false
        }
    }
}
